// ==========================================================================
//  boot_rom_pkg.sv
//  Boot ROM icerigi - bootloader makine kodu (sw_nexys/src/bootloader.S)
//
//  BU DOSYA URETILMISTIR - ELLE DUZENLEMEYIN.
//      python scripts/gen_rom_paketleri.py
//  Tutarlilik denetimi:
//      python scripts/gen_rom_paketleri.py --denetle
//
//  Tablolar packed vektorde tutulur, erisim dilimleme ile
//  yapilir. Indeks 0 vektorun EN DUSUK bitlerindedir.
//
//  fc_weights DORDE BOLUNMUSTUR (fc_weights0..3). NPU'nun FC
//  katmani dort sinif icin ayrik araliklardan okur; tek buyuk
//  ROM adres cozucusunde 4.694 fanout uretiyordu.
// ==========================================================================

package boot_rom_pkg;

    // rtl/boot/boot.hex
    //   256 giris x 32 bit = 8192 bit

    localparam logic [8191:0] BOOT_ROM_ICERIK_DUZ = 8192';

    function automatic logic [31:0] boot_rom_icerik(input logic [7:0] i);
        return BOOT_ROM_ICERIK_DUZ[i * 32 +: 32];
    endfunction

endpackage
